// 时空回溯系统 - GitHub CDN 实时热更新加载器 (sisjzknxhnsnejxn-cmyk/Time-Back)
(() => {
  const BTN_NAME = '↺ 时空回溯';
  const BTN_SEL = '#qr--bar .qr--button, #qr--bar button, #qr--bar .menu_button, .qr--buttons .qr--button, .qr--buttons button, .qr--button, .menu_button';
  let toggleFn = null, pendingOpen = false, loadFailed = false, isLoading = false;
  window.__TIMELOOP_REGISTER_TOGGLE__ = (fn) => {
    toggleFn = fn; loadFailed = false; isLoading = false;
    if (pendingOpen) { pendingOpen = false; fn(true); }
  };
  const resolveEl = (r) => (!r ? null : r.nodeType === 3 ? r.parentElement : r.nodeType === 1 ? r : null);
  function handleTrigger() {
    if (typeof toggleFn === 'function') { toggleFn(true); return; }
    pendingOpen = true;
    if (loadFailed && !isLoading) {
      if (typeof toastr !== 'undefined') toastr.info('正在重新连接云端加载时空回溯...', '', { timeOut: 2000 });
      loadRemoteBundle();
      return;
    }
    if (typeof toastr !== 'undefined') toastr.info('正在从云端加载时空回溯，完成后将自动打开...', '', { timeOut: 2000 });
  }
  try { replaceScriptButtons([{ name: BTN_NAME, visible: true }]); } catch (_) {}
  try { eventOn(getButtonEvent(BTN_NAME), () => handleTrigger()); } catch (_) {}
  try {
    const doc = window.parent && window.parent.document ? window.parent.document : document;
    let touchPos = null;
    const findBtn = (raw) => {
      const t = resolveEl(raw);
      if (!t || typeof t.closest !== 'function' || t.closest('.timeloop-root')) return null;
      const b = t.closest(BTN_SEL);
      if (!b || b.classList.contains('timeloop-qr-btn')) return null;
      const txt = (b.textContent || b.getAttribute('title') || '').trim();
      return txt.length > 0 && txt.length <= 32 && txt.includes('时空回溯') ? b : null;
    };
    const onTS = (e) => {
      if (typeof toggleFn === 'function') return;
      if (!e.touches || e.touches.length !== 1 || !findBtn(e.target)) { touchPos = null; return; }
      touchPos = { x: e.touches[0].clientX, y: e.touches[0].clientY, t: Date.now() };
    };
    const onTE = (e) => {
      if (typeof toggleFn === 'function' || !touchPos || !e.changedTouches || !e.changedTouches.length) return;
      const s = touchPos; touchPos = null;
      const c = e.changedTouches[0];
      if (Math.hypot(c.clientX - s.x, c.clientY - s.y) > 16 || Date.now() - s.t > 750 || !findBtn(e.target)) return;
      if (e.cancelable) e.preventDefault();
      handleTrigger();
    };
    const onClk = (e) => { if (typeof toggleFn !== 'function' && findBtn(e.target)) handleTrigger(); };
    doc.addEventListener('touchstart', onTS, { capture: true, passive: true });
    doc.addEventListener('touchend', onTE, { capture: true, passive: false });
    doc.addEventListener('click', onClk, true);
    if (typeof $ === 'function') {
      $(window).one('pagehide', () => {
        doc.removeEventListener('touchstart', onTS, true);
        doc.removeEventListener('touchend', onTE, true);
        doc.removeEventListener('click', onClk, true);
      });
    }
  } catch (_) {}
  async function loadRemoteBundle() {
    if (isLoading || typeof toggleFn === 'function') return;
    isLoading = true; loadFailed = false;
    const repo = 'sisjzknxhnsnejxn-cmyk/Time-Back';
    const file = 'dist/' + encodeURIComponent('时空回溯系统') + '/index.js';
    const refs = [];
    try {
      const ctrl = new AbortController(), tm = setTimeout(() => ctrl.abort(), 1800);
      const res = await fetch(`https://api.github.com/repos/${repo}/commits/main`, { cache: 'no-store', signal: ctrl.signal });
      clearTimeout(tm);
      if (res.ok) { const d = await res.json(); if (d && d.sha) refs.push(d.sha); }
    } catch (_) {}
    refs.push('main');
    const urls = [], bust = Date.now();
    for (const r of refs) {
      for (const h of ['testingcf.jsdelivr.net', 'fastly.jsdelivr.net', 'cdn.jsdelivr.net', 'gcore.jsdelivr.net']) {
        urls.push(`https://${h}/gh/${repo}@${r}/${file}?t=${bust}`);
      }
    }
    urls.push(`https://raw.githubusercontent.com/${repo}/main/${file}?t=${bust}`);
    for (const u of urls) {
      const ctrl = new AbortController(), tm = setTimeout(() => ctrl.abort(), 6500);
      try {
        const res = await fetch(u, { cache: 'no-store', signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        const code = await res.text();
        if (!code || code.length < 100) throw new Error('Empty');
        clearTimeout(tm);
        new Function(code)();
        isLoading = false; loadFailed = false; return;
      } catch (e) { clearTimeout(tm); }
    }
    isLoading = false; loadFailed = true;
    if (typeof toastr !== 'undefined') toastr.error('云端脚本加载失败，再次点击「↺ 时空回溯」可重试');
  }
  loadRemoteBundle();
})();
